INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 15, 'theory', 'Quiz: zones and regions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 0, 'What is a failure domain?', '["A type of database", "A group of resources that break at the same time: host, rack, zone, region", "A service name", "A replication protocol"]', 1, 'Copies are placed in different failure domains so that losing one does not take away all the copies.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 1, 'Why is synchronous replication possible between zones of one region but usually not between regions?', '["There is no network between zones", "Latency between zones is ~1 ms, between regions tens or hundreds of ms", "Regions do not support replication", "Zones are more expensive"]', 1, 'A synchronous write waits for acknowledgment: hundreds of ms on every operation is unacceptable.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 2, 'What is the risk of geo-DNS during a region failover?', '["It encrypts the traffic", "Clients cache the old address for a few more minutes, so the TTL is kept short", "DNS does not work with regions", "It increases latency forever"]', 1, 'Record caching slows the failover; a short TTL and a global load balancer help.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 3, 'What danger is often missed in a two-region setup?', '["Too many servers", "Shared dependencies (DNS, certificates, configuration) located in one region", "Replicas that are too expensive", "Extra metrics"]', 1, 'A shared service in one region takes down both; every dependency must be checked.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 4, 'What does a cell-based architecture give you?', '["Cheaper storage", "It limits the blast radius: a failure or bad deploy affects only a share of users", "It speeds up the network", "It removes databases"]', 1, 'Each cell is an independent instance of the service for part of the users.');
